import{_ as d,o as e,c as o,a2 as c}from"./chunks/framework.BM5YPQmL.js";const m=JSON.parse('{"title":"常见错误 — 高频清单","description":"","frontmatter":{},"headers":[],"relativePath":"zh/troubleshooting/common-errors.md","filePath":"zh/troubleshooting/common-errors.md"}'),r={name:"zh/troubleshooting/common-errors.md"};function a(l,t,s,n,i,h){return e(),o("div",null,[...t[0]||(t[0]=[c(`<h1 id="常见错误-—-高频清单" tabindex="-1">常见错误 — 高频清单 <a class="header-anchor" href="#常见错误-—-高频清单" aria-label="Permalink to &quot;常见错误 — 高频清单&quot;">​</a></h1><p>你实际会撞上的错误，按频率从高到低，每条按 <strong>症状 → 原因 → 修复</strong>组织。这是短清单；完整的 逐子系统清单（含排查链）是 <a href="./error-catalog.html">error-catalog.md</a>；什么都不打印的失败是 <a href="./silent-failures.html">silent-failures.md</a>。</p><h2 id="日志与-watchdog-错误" tabindex="-1">日志与 watchdog 错误 <a class="header-anchor" href="#日志与-watchdog-错误" aria-label="Permalink to &quot;日志与 watchdog 错误&quot;">​</a></h2><table tabindex="0"><thead><tr><th>症状</th><th>原因</th><th>修复</th></tr></thead><tbody><tr><td><code>logcat: bad level (debug/info/warn/error/fatal or 0-4)</code></td><td>级别拼写错误</td><td><code>logcat -l warn</code> 或 <code>-l 2</code></td></tr><tr><td><code>klog: flush FAILED (no filesystem mounted?)</code>（rotate/export 孪生）</td><td>/var/log 没有卷支撑</td><td>挂载一个；<code>logctl flush</code> 随后写入 <code>/var/log/kernel.log</code></td></tr><tr><td><code>logctl: bad level (&#39;-&#39; = any)</code></td><td>过滤语法</td><td><code>logctl filter &lt;clear|[level] [module] [keyword]&gt;</code></td></tr><tr><td>dmesg 页脚显示 <code>dropped &lt;N&gt;</code></td><td>1024 条环形已回绕</td><td><code>dmesg 1024</code>；考虑 <code>logctl threshold</code> + <code>flush</code></td></tr><tr><td>你期待的消息从不出现</td><td>级别被禁或过滤器生效</td><td><code>logctl status</code>；<code>logctl test</code> 校准管线（5 行，模块 <code>klogtest</code>）</td></tr><tr><td><code>watchdog: register FAILED (table full?)</code></td><td>最多 8 槽</td><td><code>watchdog slots</code>；先停一个</td></tr><tr><td><code>watchdog hw: start FAILED (bad timeout?)</code></td><td>TCO 范围是 2..63 s</td><td><code>watchdog hw start 30</code></td></tr><tr><td><code>watchdog hw: feed FAILED (not armed?)</code></td><td>start 之前就 feed</td><td>先 <code>watchdog hw start</code></td></tr><tr><td><code>health: export FAILED (no filesystem mounted?)</code></td><td>导出目标缺失</td><td>挂载一个卷；<code>health export /mnt/health.txt</code></td></tr></tbody></table><h2 id="tui-与显示错误" tabindex="-1">TUI 与显示错误 <a class="header-anchor" href="#tui-与显示错误" aria-label="Permalink to &quot;TUI 与显示错误&quot;">​</a></h2><table tabindex="0"><thead><tr><th>症状</th><th>原因</th><th>修复</th></tr></thead><tbody><tr><td><code>tui</code> 页面经脚本不打印任何内容</td><td>TUI op 走 DIRECT 路由，绕过捕获</td><td>交互式运行 <code>tui</code>；只有 <code>tui-test</code> 经捕获提供文本</td></tr><tr><td><code>page &#39;%s&#39; failed (rc=%d)</code> / <code>tui: desktop init failed</code></td><td>桌面内部问题</td><td><code>dmesg 100</code>；附串口捕获报告</td></tr><tr><td><code>value out of range (1980-2099, ...)</code>（时间页）</td><td>RTC 设置防护</td><td>设置合法日期</td></tr><tr><td><code>volume: device rejected the level</code>（硬件页）</td><td>混音器钳制</td><td>用 0-100</td></tr><tr><td>编辑器 <code>[save failed]</code></td><td>只读文件系统或部分缓冲</td><td>检查 <code>mounts</code>；<code>[PARTIAL: save refused]</code> = 超限文件</td></tr><tr><td>中文显示为按键或豆腐块</td><td>locale/编码不匹配</td><td><code>lang zh</code>、<code>serial_encoding utf8</code>（与你的终端匹配）</td></tr></tbody></table><h2 id="ocse-安装器错误-来自安装介质" tabindex="-1">OCSE 安装器错误（来自安装介质） <a class="header-anchor" href="#ocse-安装器错误-来自安装介质" aria-label="Permalink to &quot;OCSE 安装器错误（来自安装介质）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>症状</th><th>原因</th><th>修复</th></tr></thead><tbody><tr><td><code>ocblmbr.bin MISSING</code> / <code>ocos.tar MISSING</code></td><td>介质不完整</td><td>重新下载 ISO；核对大小/SHA</td></tr><tr><td><code>install: FATAL - extraction failed</code></td><td>ocos.tar 损坏</td><td>同上</td></tr><tr><td><code>mkpart failed</code> / <code>created partition not found</code></td><td>目标磁盘问题</td><td>先跑磁盘检查；换一块盘</td></tr><tr><td><code>install: FATAL - could not set the boot flag</code></td><td>分区表写入失败</td><td>重跑；检查介质</td></tr><tr><td>安装后安装器设置被忽略</td><td>BUG-129 配置方言分裂</td><td>从运行中的系统再次设键：<code>config set shell.lang zh</code></td></tr><tr><td>OCSE GUI 点击无效</td><td>BUG-113</td><td>CLI 热键 Ctrl+Alt+F2，或 <code>click &lt;x&gt; &lt;y&gt;</code> 命令</td></tr></tbody></table><h2 id="电源错误" tabindex="-1">电源错误 <a class="header-anchor" href="#电源错误" aria-label="Permalink to &quot;电源错误&quot;">​</a></h2><table tabindex="0"><thead><tr><th>症状</th><th>原因</th><th>修复</th></tr></thead><tbody><tr><td><code>Suspend not supported (ACPI required).</code></td><td>机器无 ACPI 表</td><td>某些 VM/老主板属预期</td></tr><tr><td><code>S3 resume failed.</code></td><td>恢复路径损坏</td><td>报告；有数据丢失风险 — 先保存</td></tr><tr><td><code>System halted.</code> 然后没有别的</td><td>这就是 halt 成功消息</td><td>在宿主机侧断电</td></tr></tbody></table><h2 id="恢复环境-ocire-错误" tabindex="-1">恢复环境（OCIRE）错误 <a class="header-anchor" href="#恢复环境-ocire-错误" aria-label="Permalink to &quot;恢复环境（OCIRE）错误&quot;">​</a></h2><table tabindex="0"><thead><tr><th>症状</th><th>原因</th><th>修复</th></tr></thead><tbody><tr><td><code>Supervisor: no OCIRE recovery volume found</code></td><td>hd1 0xEE+FAT12 卷缺失</td><td>带恢复分区重新安装（OCSE 会创建）</td></tr><tr><td><code>logread: BAD ring header (magic/cursor)</code></td><td>引导日志环形损坏</td><td><code>repair quick</code> 重置它</td></tr><tr><td><code>WARNING: log agent digest mismatch</code></td><td>代理镜像与邮箱摘要不符（防篡改）</td><td><code>syscheck</code>，然后 <code>repair</code></td></tr><tr><td>修复期间 <code>REBUILD FAILED</code> / <code>RESET FAILED</code></td><td>黄金集或介质损坏</td><td>重跑；换一个黄金集</td></tr><tr><td><code>oc&gt;</code> 中 <code>Unknown command: &lt;cmd&gt;</code></td><td>恢复 shell 很小</td><td><code>help</code> 列出它；隐藏附加：<code>lang [en|zh]</code></td></tr></tbody></table><h2 id="万用第一步" tabindex="-1">万用第一步 <a class="header-anchor" href="#万用第一步" aria-label="Permalink to &quot;万用第一步&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; health          # alarms: memory &gt;90%, tasks &gt;64, CPU &gt;=90%x10s</span></span>
<span class="line"><span>ush&gt; dmesg 100       # the kernel log tail (ring 1024)</span></span>
<span class="line"><span>ush&gt; crashlog        # panics you may not have seen (32-slot ring)</span></span></code></pre></div><hr><h2 id="shell-与文件工具" tabindex="-1">Shell 与文件工具 <a class="header-anchor" href="#shell-与文件工具" aria-label="Permalink to &quot;Shell 与文件工具&quot;">​</a></h2><table tabindex="0"><thead><tr><th>症状</th><th>原因</th><th>修复</th></tr></thead><tbody><tr><td><code>ush: command not found: &lt;cmd&gt;</code></td><td>拼写错误，或程序不在注册表中</td><td><code>help -a</code>（或分组的 <code>help -w</code>）；查 <a href="./../manual/function-dictionary.html">../manual/function-dictionary.md</a></td></tr><tr><td><code>ush: syntax error near &#39;&gt;&#39;</code>（或 <code>&#39;&lt;&#39;</code>）</td><td>空重定向目标</td><td>给出文件名：<code>cmd &gt; file</code></td></tr><tr><td><code>ush: &#39;exit&#39; is not available; ...</code></td><td>按设计 — ush 是启动项</td><td><code>shutdown</code> / <code>reboot</code></td></tr><tr><td><code>ush: job control requires external programs</code></td><td><code>fg</code>/<code>bg</code> 被识别但未实现</td><td>用 <code>jobs</code> 列出；没有恢复功能</td></tr><tr><td><code>cat: cannot open &lt;path&gt;</code>（同 head/tail/sort/uniq/wc/awk）</td><td>sys_open 失败：文件缺失、cwd 错误</td><td><code>pwd</code>、<code>ls</code>；路径相对 shell cwd</td></tr><tr><td><code>mkdir: cannot create &#39;&lt;path&gt;&#39;</code></td><td>已存在，或父目录缺失</td><td>先创建父目录</td></tr><tr><td><code>rm: cannot remove &#39;&lt;path&gt;&#39;</code> / <code>rmdir: ...</code></td><td>文件忙（打开的 fd），或目录非空</td><td>关闭它；<code>ls</code> 该目录</td></tr><tr><td><code>ln: cannot create symlink (target must be an absolute path)</code></td><td>符号链接目标仅限绝对路径</td><td><code>ln -s /abs/target link</code></td></tr><tr><td><code>sed: unknown script</code></td><td>只有 <code>s/old/new/[g]</code>、<code>-n Np</code>、<code>Nd</code></td><td>见 <a href="./../manual/ush-reference.html">../manual/ush-reference.md</a></td></tr><tr><td><code>awk: missing {print ...}</code></td><td>微型 awk 仅支持 <code>{print ...}</code></td><td>同上</td></tr><tr><td><code>help: unknown option &#39;&lt;o&gt;&#39;</code></td><td>只有 <code>-a</code>/<code>--all</code>、<code>-w</code>/<code>--wp</code></td><td><code>help -a</code></td></tr><tr><td><code>run: unknown program: &lt;name&gt;</code></td><td>注册表查找失败</td><td><code>help -a</code>；注册表在构建时冻结为 284</td></tr><tr><td><code>ls *</code> 列出名为 <code>*</code> 的字面文件</td><td><strong>任何地方都没有 globbing</strong>（ush 和 ls）</td><td>显式给出文件名</td></tr><tr><td><code>disk-tool: unknown op: &lt;op&gt;</code>（任意 mega 应用）</td><td>逐字表未命中</td><td>该应用的 <code>usage:</code> 列出其表；<code>help -w</code> 分组全部命令</td></tr><tr><td><code>&lt;app&gt;: service call failed (rc=-1)</code>（250 个应用共享）</td><td>L1SVC 桥返回 -1</td><td>重跑；<code>dmesg 100</code>；该家族的 <code>_test</code> 桩；然后 <a href="./error-catalog.html">error-catalog.md</a> §7.1</td></tr><tr><td>nano/vi 退出后屏幕残留</td><td>BUG-111（编辑器残影）</td><td><code>clear</code></td></tr><tr><td>屏幕上中文为豆腐块（串口正常）</td><td>BUG-110/130 控制台回退 UTF-8</td><td>当前构建已修复；更新镜像</td></tr><tr><td>编辑器：<code>[PARTIAL: save refused]</code></td><td>文件超过 256 行 × 128 字节</td><td>按设计（BUG-34 修复）；拆分文件</td></tr></tbody></table><h2 id="网络" tabindex="-1">网络 <a class="header-anchor" href="#网络" aria-label="Permalink to &quot;网络&quot;">​</a></h2><table tabindex="0"><thead><tr><th>症状</th><th>原因</th><th>修复</th></tr></thead><tbody><tr><td><code>DHCP failed (timeout)</code></td><td>无 OFFER/ACK — user-net 缺失、线缆或服务器</td><td><code>ip</code>（0.0.0.0?），再 <code>dhcp</code>；QEMU：<code>-netdev user,id=n1 -device e1000,netdev=n1</code></td></tr><tr><td><code>DNS resolution failed</code> / <code>(timeout)</code></td><td>无 DNS 服务器，或 UDP 被阻断</td><td>重跑 <code>dhcp</code>（它会设置 DNS）；<code>dns &lt;host&gt;</code> 测试；见 <a href="./network-issues.html">network-issues.md</a></td></tr><tr><td><code>ping</code> 先不打印然后失败</td><td>名称解析先失败（&quot;Resolving...&quot;）</td><td><code>dns &lt;host&gt;</code>；或直接 ping IP</td></tr><tr><td><code>connect failed</code></td><td>路由/防火墙</td><td><code>route</code>（网关在吗？）、<code>firewall</code> 列表，试验时 <code>firewall reset</code></td></tr><tr><td><code>wget: cannot create file, printing to console:</code></td><td>目标路径不可写</td><td>检查 <code>pwd</code>/挂载；正文仍打印到控制台</td></tr><tr><td><code>TLS failed (code &lt;n&gt;)</code> / <code>[tls] x509 verify failed: ... REFUSED</code></td><td>信任决策 — 自签名/无锚链<strong>默认</strong>被拒</td><td>修正服务器证书；仅测试的选择加入：<code>config set tls.insecure 1</code></td></tr><tr><td><code>[ssh] HOST SIGNATURE INVALID - disconnecting</code></td><td>TOFU 不匹配</td><td><code>[ssh] WARNING: HOST KEY CHANGED!</code> 表示必须刻意重新信任 <code>/etc/ssh_known_hosts</code> 中的条目</td></tr><tr><td><code>[ssh] USERAUTH_FAILURE — wrong password</code></td><td>凭据</td><td>默认用户 <code>oc</code> / 密码 <code>oc</code>；公钥 = 密码 <code>-</code> 加 <code>/etc/ssh_client_key</code></td></tr><tr><td><code>sshd</code> 拒绝启动：<code>cannot obtain a per-installation host key</code></td><td>无密钥且无法生成</td><td>预置 <code>etc.img</code>（<code>tools/host_keygen_etc.py</code>），或释放内存重试（首次启动会后台生成）</td></tr><tr><td>首次连接 sshd 停滞</td><td>DHCP 后 ARP 缓存冷</td><td>先热身：<code>ping &lt;peer&gt;</code></td></tr><tr><td><code>e1000e: init failed</code>（任意 <code>&lt;nic&gt;: init failed</code>）</td><td>驱动探针失败 — 卡缺失、BAR 损坏、DMA 不可达</td><td><code>lspci</code> → <code>pcidump &lt;b:d.f&gt;</code> → 家族状态 → 家族 <code>_test</code>；模板见 <a href="./network-issues.html">network-issues.md</a></td></tr><tr><td><code>virtio TX timeout: avail_idx=...</code></td><td>virtio NIC 停止消费描述符</td><td>重启 VM/设备；若持续则报告</td></tr><tr><td><code>wifi scan</code> 不打印网络</td><td>QEMU 无射频 — 如实输出</td><td>真实硬件，或跳过</td></tr></tbody></table><h2 id="存储与文件系统" tabindex="-1">存储与文件系统 <a class="header-anchor" href="#存储与文件系统" aria-label="Permalink to &quot;存储与文件系统&quot;">​</a></h2><table tabindex="0"><thead><tr><th>症状</th><th>原因</th><th>修复</th></tr></thead><tbody><tr><td><code>mount: failed</code> / <code>vfs_mount: unknown fs type</code></td><td>类型/设备/参数错误，或该 fs 不受支持</td><td><code>lsblk</code>、<code>mounts</code>；类型：ramfs/fat32/exfat/ext4</td></tr><tr><td><code>fat32: not a FAT32 volume (FAT12/16 detected)</code> / <code>invalid BPB</code></td><td>设备节点错误，或不是 FAT32</td><td><code>fatstat &lt;dev&gt;</code> 显示解析的 BPB；节点错？<code>lsblk</code></td></tr><tr><td><code>ext4: unsupported INCOMP feature bits ... mount refused</code></td><td>ext4 驱动只读且有特性限制</td><td>挂载更简单的 ext4，或在别处读取</td></tr><tr><td><code>umount: target is busy - close open files first</code></td><td>打开的 fd</td><td>关闭它们；<code>umount: unmount nested mounts first</code> → 先子挂载（<code>mounts</code> 显示嵌套）</td></tr><tr><td><code>umount: cannot unmount the root filesystem</code></td><td>按设计</td><td>—</td></tr><tr><td><code>fsck: not a FAT32 volume (fsck supports FAT32 only; ...)</code></td><td>fsck 仅支持 FAT32</td><td>在别处修复；<code>fatstat</code> 确认</td></tr><tr><td><code>parted: device not found</code> / <code>mkfs.*: device not found</code></td><td>设备字符串错误</td><td>先 <code>lsblk</code>；名字必须精确</td></tr><tr><td><code>mkfs.exfat: device too small (need at least 65 sectors, got &lt;N&gt;)</code></td><td>目标过小</td><td>更大的设备</td></tr><tr><td><code>grub-install: MBR gap too small for &lt;N&gt;</code></td><td>MBR 后间隙放不下 core.img</td><td>以 ≥ 1 MiB 间隙重新分区（或 GPT）</td></tr><tr><td><code>install: disk too large for MBR (&gt;2TiB) or too small</code></td><td>MBR 限制</td><td>用 ≤ 2 TiB 的目标</td></tr><tr><td>重启后写入丢失</td><td>它们活在 ramfs 上 — 只有 /etc 和已挂载卷持久</td><td><code>mounts</code> 显示什么持久；电源操作前 <code>sync</code></td></tr><tr><td>U 盘出现后又消失</td><td>MSC 拔出路径</td><td><code>usb_hotplug_test</code> 复现；重新插拔</td></tr><tr><td><code>blk: write to protected device ... REFUSED (ocire recovery disk)</code></td><td>整盘 OCIRE 保护（仅 klog 行）</td><td>按设计 — 仅从 OCIRE <code>repair</code> 修改该卷</td></tr><tr><td><code>abdisk</code> 之后 A/B 磁盘&quot;absent&quot;</td><td>服务缓存尚未刷新</td><td>重跑 <code>update status</code>；向导会循环复查</td></tr><tr><td><code>blkcache: alloc FAILED - cache disabled (raw I/O)</code></td><td>缓存表分配失败；系统继续无缓存</td><td><code>mem</code>；若持续则报告</td></tr></tbody></table><h2 id="更新-ota" tabindex="-1">更新 / OTA <a class="header-anchor" href="#更新-ota" aria-label="Permalink to &quot;更新 / OTA&quot;">​</a></h2><table tabindex="0"><thead><tr><th>症状</th><th>原因</th><th>修复</th></tr></thead><tbody><tr><td><code>update</code> 不打印 / &quot;up to date&quot; 但你预期有更新</td><td>六因静默链</td><td>走 <a href="./silent-failures.html">silent-failures.md</a> §7；或直接跑向导：<code>update</code>（无参数）</td></tr><tr><td><code>update: cannot determine target slot (not booted from A/B?)</code></td><td>从 ISO 引导，无 A/B 布局</td><td><code>update status</code>；<code>abdisk &lt;dev&gt;</code> 创建（destructive）</td></tr><tr><td><code>update: download failed: &lt;why&gt;</code></td><td>网络 / 服务器</td><td><code>&lt;why&gt;</code> 是 OC_UPDATE_E_* 文本 — <a href="./error-codes.html">error-codes.md</a> §1</td></tr><tr><td><code>SHA256 mismatch</code> / <code>package (tar.gz) invalid</code></td><td>下载损坏</td><td>重新下载；核对大小</td></tr><tr><td><code>config: write rejected (empty, non-ASCII, too long, or invalid value)</code></td><td>从严的值防护</td><td><code>config list</code> 看格式；仅 ASCII 值</td></tr><tr><td><code>config: cannot read /etc/opencube.conf</code></td><td>/etc 未挂载</td><td><a href="./storage-issues.html">storage-issues.md</a></td></tr></tbody></table><h2 id="内核-引导-崩溃" tabindex="-1">内核 / 引导 / 崩溃 <a class="header-anchor" href="#内核-引导-崩溃" aria-label="Permalink to &quot;内核 / 引导 / 崩溃&quot;">​</a></h2><table tabindex="0"><thead><tr><th>症状</th><th>原因</th><th>修复</th></tr></thead><tbody><tr><td><code>*** KERNEL PANIC: &lt;reason&gt; ***</code></td><td>11 个可能位点 — 原因串指名它</td><td><a href="./error-codes.html">error-codes.md</a> §panic-sites；串口是权威；重启后 <code>crashlog</code></td></tr><tr><td>机器&quot;自己&quot;重启</td><td>策略为 REBOOT 的 panic、watchdog、或 OCBL 判定停滞</td><td><code>crashlog</code>、<code>dmesg</code>、<code>/var/log/crash.log</code>；OCBL 侧：<a href="./boot-failures.html">boot-failures.md</a></td></tr><tr><td>整机冻结，无 panic（快速连打 &#39;a&#39;/&#39;u&#39;，或 <code>loop</code>）</td><td>BUG-109 冻结竞态 / BUG-112 loop 遏制缺口</td><td>捕获 <code>-serial file:</code> 并报告；避免与控制台输入赛跑</td></tr><tr><td><code>[user] process table full (max &lt;N&gt; processes)</code></td><td>进程过多</td><td><code>ps</code>；<code>kill &lt;pid&gt;</code></td></tr><tr><td><code>[user] not an ELF file</code></td><td>exec 目标不是 ELF64</td><td>对 badapp 类固定件属预期；检查二进制</td></tr><tr><td><code>KERNEL PANIC (no crash handler installed): &lt;reason&gt;</code></td><td>崩溃服务注册前的 panic</td><td>早引导 bug 类；捕获串口，报告</td></tr><tr><td>引导停在 <code>FAIL</code> 阶段行</td><td>该子系统初始化失败</td><td><a href="./boot-failures.html">boot-failures.md</a>；FAIL 之上的消息指名设备</td></tr><tr><td><code>Power off not supported. System halted.</code></td><td>电源端口穷尽（VM）</td><td>使用宿主机电源控制</td></tr><tr><td><code>sleep: invalid time</code></td><td>非数值/负参数</td><td><code>sleep 2</code>、<code>sleep 0.5</code></td></tr></tbody></table><h2 id="音频-usb-杂项硬件" tabindex="-1">音频 / USB / 杂项硬件 <a class="header-anchor" href="#音频-usb-杂项硬件" aria-label="Permalink to &quot;音频 / USB / 杂项硬件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>症状</th><th>原因</th><th>修复</th></tr></thead><tbody><tr><td><code>play: device error</code> / <code>: unknown device &#39;&lt;name&gt;&#39;</code></td><td>无此音频设备</td><td><code>sound</code> 列出已注册设备</td></tr><tr><td><code>[audio_rw_test] no sound cards registered =&gt; SKIPPED</code></td><td>未接音频设备</td><td>QEMU：<code>-device intel-hda</code>；否则如实跳过</td></tr><tr><td>QEMU hda 在 44.1 kHz 冻结</td><td>QEMU-10 模型死循环（源内有记载）</td><td>真实硬件正常；其他采样率可用</td></tr><tr><td><code>usb: SET_ADDRESS failed</code> / <code>GET_DESCRIPTOR(...) failed</code></td><td>设备未枚举</td><td>重新插拔；<code>usb</code>，然后 <code>usb_storage_test</code></td></tr><tr><td><code>virtio-blk: write rejected (device is read-only)</code></td><td>QEMU 驱动器是 readonly=on</td><td>按设计；去掉该 flag</td></tr><tr><td><code>no hardware watchdog present</code> 行</td><td>无 WDAT/TCO — 探针如实</td><td>q35 有 TCO；默认 pc 没有</td></tr><tr><td>self-IPI 通过但 <code>msitest: FAIL</code></td><td>MSI 路由损坏</td><td><code>pcibars</code>、<code>pcie</code>，报告</td></tr><tr><td><code>date: ms since boot (no RTC driver)</code></td><td>无 CMOS RTC（VM 默认）</td><td>QEMU 中 <code>-rtc base=...</code>；信息性</td></tr></tbody></table><h2 id="构建期-宿主机" tabindex="-1">构建期（宿主机） <a class="header-anchor" href="#构建期-宿主机" aria-label="Permalink to &quot;构建期（宿主机）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>症状</th><th>原因</th><th>修复</th></tr></thead><tbody><tr><td><code>grub-mkimage: cannot open ... unicode.pf2</code></td><td>字体在 grub-common 中</td><td>安装它 / 让 OC_TOOLS 指向含 <code>usr/share/grub/unicode.pf2</code> 的树</td></tr><tr><td><code>src-zip: not a git checkout</code></td><td>无 git 元数据</td><td>从克隆构建或用 <code>make dist</code></td></tr><tr><td><code>error: operand size mismatch for &#39;setc&#39;</code></td><td>新 GAS 上的修复前代码树</td><td>更新越过 u8-flag 修复</td></tr><tr><td>新 GCC 上的 packed-member 警告</td><td>修复前代码树</td><td>更新（packed 标签类型）</td></tr><tr><td><code>embed_grub: missing /usr/usr/lib/grub...</code></td><td>修复前脚本</td><td>更新（双布局探测）</td></tr><tr><td><code>chinese_font gz layout mismatch - regenerate ...</code></td><td>字体 blob 与头文件漂移</td><td>重新生成 chinese_font_data.c</td></tr><tr><td>某个 <code>_Static_assert</code> 触发</td><td>跨模块布局契约漂移</td><td>断言消息指名两侧 — <a href="./error-codes.html">error-codes.md</a> §static-asserts</td></tr></tbody></table><h2 id="测试门" tabindex="-1">测试门 <a class="header-anchor" href="#测试门" aria-label="Permalink to &quot;测试门&quot;">​</a></h2><ul><li>SSH E2E 需要预置的主机密钥（<a href="./../dev/e2e-suites.html">../dev/e2e-suites.md</a> 中的 mtools 配方）。</li><li>HTTPS E2E 第 0 项要求自签名链被拒绝 — 如果 连上了，检查 <code>tls.insecure</code> 为 0。</li><li>回归套件需要 pexpect；SSH 套件需要 paramiko。</li><li>串口抖动？见 <a href="./silent-failures.html">silent-failures.md</a> §8 和 <a href="./qemu-debugging.html">qemu-debugging.md</a> §errata。</li></ul><h2 id="下一步去哪" tabindex="-1">下一步去哪 <a class="header-anchor" href="#下一步去哪" aria-label="Permalink to &quot;下一步去哪&quot;">​</a></h2><table tabindex="0"><thead><tr><th>如果错误是...</th><th>前往</th></tr></thead><tbody><tr><td>数值代码或 panic 横幅</td><td><a href="./error-codes.html">error-codes.md</a></td></tr><tr><td>来自特定子系统的消息串</td><td><a href="./error-catalog.html">error-catalog.md</a></td></tr><tr><td>完全不打印</td><td><a href="./silent-failures.html">silent-failures.md</a></td></tr><tr><td>引导期间 / OCBL / OCIRE 中</td><td><a href="./boot-failures.html">boot-failures.md</a></td></tr><tr><td>网络形状</td><td><a href="./network-issues.html">network-issues.md</a></td></tr><tr><td>磁盘/文件系统形状</td><td><a href="./storage-issues.html">storage-issues.md</a></td></tr><tr><td>仅在 QEMU 中</td><td><a href="./qemu-debugging.html">qemu-debugging.md</a></td></tr><tr><td>你找不到的命令</td><td><a href="./../manual/function-dictionary.html">../manual/function-dictionary.md</a></td></tr></tbody></table>`,33)])])}const g=d(r,[["render",a]]);export{m as __pageData,g as default};
